rs label{display:grid;gap:3px;color:var(--mrs-muted);font-size:10px;font-weight:800}
.chartRegistryFilters input,.chartRegistryFilters select{width:100%;min-width:0}
.chartCandidateList{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:8px}
.chartCandidateCard{display:grid;gap:8px;min-width:0;border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-md);background:var(--mrs-surface-2);padding:10px}
.chartCandidateCard.diagnostic{border-style:dashed}
.chartCandidateTitle{display:flex;justify-content:space-between;gap:8px}
.chartCandidateCard dl{display:grid;grid-template-columns:1fr 1fr;gap:5px 8px;margin:0}
.chartCandidateCard dl div{min-width:0}
.chartCandidateCard dt,.chartCandidateSource{color:var(--mrs-muted);font-size:10px}
.chartCandidateCard dd{margin:0;overflow:hidden;color:var(--mrs-text);font-size:11px;font-weight:750;text-overflow:ellipsis;white-space:nowrap}
.chartVisualWorkspace,.chartCatalog,.chartSelectedPreview{display:grid;gap:8px;margin-top:9px;padding-top:9px;border-top:1px solid var(--mrs-border)}
.chartSelectedPreview{padding:10px;border:1px solid rgba(49,92,246,.35);border-radius:var(--mrs-radius-lg);background:rgba(49,92,246,.06)}
.chartSelectedPreview .autoChartCard{max-width:760px}
.chartCatalog{margin-top:12px}
.chartFamilyVariantTitle{min-height:28px;color:var(--mrs-muted);font-size:11px}
.chartFamilyAggregation{display:grid;gap:3px;color:var(--mrs-muted);font-size:10px}
.chartFamilyAggregation select{width:100%;min-width:0;height:28px}
.chartFamilyMiniChart{min-height:120px;max-height:180px;border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-md);background:var(--mrs-surface-2);margin:6px 0;overflow:hidden;display:flex;align-items:center;justify-content:center}
.chartCandidateActions{margin-top:auto;padding:0 10px 9px}
.chartCandidateCard .chartCandidateActions{padding:0}
.chartRegistryPager{justify-content:space-between;margin-top:9px;color:var(--mrs-muted);font-size:11px}
.pdfDiagnostics{display:grid;gap:8px;margin-bottom:9px;padding:10px;border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-lg);background:var(--mrs-surface-2)}
.pdfDiagnostics p{margin:0;color:var(--mrs-text);font-size:12px}
.pdfDiagnostics dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:7px;margin:0;min-width:0}
.pdfDiagnostics dl div{min-width:0;padding:6px;border-radius:8px;background:var(--mrs-surface-1)}
.pdfDiagnostics dt{color:var(--mrs-muted);font-size:10px}.pdfDiagnostics dd{min-width:0;max-width:100%;margin:2px 0 0;font-size:12px;font-weight:800;overflow-wrap:anywhere;word-break:break-word}
.analysisProgress{display:grid;grid-template-columns:minmax(180px,auto) minmax(140px,1fr) auto;align-items:center;gap:10px;border:1px solid rgba(91,130,255,.4);border-radius:var(--mrs-radius-md);background:rgba(49,92,246,.09);padding:8px 10px}
.analysisProgress b,.analysisProgress span{display:block}
.analysisProgress span{color:var(--mrs-muted);font-size:10px}
.analysisProgressTrack{height:7px;overflow:hidden;border-radius:999px;background:var(--soft)}
.analysisProgressTrack i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--brand),var(--brand2))}
.sourceAnchorBar{margin:7px 0;border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-sm);background:var(--mrs-surface-2);color:var(--mrs-muted);padding:7px 9px;font-size:11px}
.documentOverview{display:grid;gap:8px;margin-bottom:10px;border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-md);background:var(--mrs-surface-2);padding:10px}
.documentOverviewHead,.documentOverviewHead>div{display:flex;align-items:center;justify-content:space-between;gap:7px;flex-wrap:wrap}
.documentOverviewHead>div{justify-content:flex-start}
.documentOverviewHead>span{color:var(--mrs-muted);font-size:11px}
.documentWarnings{display:grid;gap:4px;color:var(--mrs-warning);font-size:11px}
.extractedTableList{display:flex;gap:6px;flex-wrap:wrap}
.extractedTableList button{display:grid;justify-items:start;text-align:left}
.extractedTableList button span{color:var(--mrs-muted);font-size:10px;font-weight:500}
.autoInsightList{
  display:grid;
  gap:8px;
  margin:0;
  padding:0;
  list-style:none;
}
.autoInsightList li{
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-sm);
  background:var(--mrs-surface-2);
  padding:9px 10px;
  color:var(--mrs-text);
  line-height:1.35;
}
.simpleEmptyDrop{
  cursor:pointer;
}
.simpleTableShell{
  display:flex;
  flex-direction:column;
  gap:9px;
  min-height:0;
}
.simpleTableTop,.simpleTableControls,.simpleFilterBar,.simpleColumnTypes{
  display:flex;
  align-items:center;
  gap:7px;
  flex-wrap:wrap;
}
.simpleTableControls #simpleTableSearch{
  flex:1 1 240px;
  min-width:160px;
}
.simpleSort,.simpleFilter{
  display:flex;
  align-items:center;
  gap:5px;
  color:var(--mrs-muted);
  font-size:11px;
  font-weight:850;
}
.simpleFilter select{
  min-width:145px;
}
.simpleColumnPicker{
  position:relative;
}
.simpleColumnPicker>summary{
  list-style:none;
  cursor:pointer;
}
.simpleColumnPicker>summary::-webkit-details-marker{
  display:none;
}
.simpleColumnPicker .checks{
  position:absolute;
  right:0;
  z-index:5;
  width:min(560px,80vw);
  max-height:320px;
  overflow:auto;
  margin-top:6px;
  padding:8px;
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface);
  box-shadow:var(--mrs-shadow-panel);
}
.simpleColumnCheck small{
  color:var(--mrs-muted);
}
.columnTypeBadge{
  display:inline-flex;
  align-items:center;
  gap:5px;
  border:1px solid var(--mrs-border);
  border-radius:999px;
  background:var(--mrs-surface-2);
  color:var(--mrs-muted);
  padding:3px 7px;
  font-size:11px;
}
.columnTypeBadge b{
  color:var(--mrs-text);
  font-size:10px;
}
.dataQualityPanel{border:1px solid var(--mrs-border);border-radius:var(--mrs-radius-md);background:var(--mrs-surface-2)}
.dataQualityPanel>summary{display:flex;justify-content:space-between;gap:8px;cursor:pointer;padding:8px 10px;color:var(--mrs-text)}
.dataQualityPanel>summary span{color:var(--mrs-muted);font-size:10px}
.dataQualityPanel[open]{padding-bottom:8px}
.dataQualityPanel[open]>.sourceAnchorBar,.dataQualityPanel[open]>.simpleTableWrap,.dataQualityPanel[open]>.hint{margin-left:8px;margin-right:8px}
.dataQualityPanel .simpleTableWrap{min-height:0;max-height:300px}
.simpleContentGrid{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(260px,340px);
  gap:10px;
  min-height:0;
}
.simpleTableWrap{
  overflow:auto;
  min-height:230px;
  max-height:52vh;
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface-2);
}
.simplePreviewTable th,.simplePreviewTable td{
  white-space:normal;
  word-break:break-word;
  overflow-wrap:anywhere;
  max-width:320px;
  vertical-align:top;
}
.simplePreviewTable th{
  position:sticky;
  top:0;
  background:var(--mrs-surface-2);
  font-size:11px;
  color:var(--mrs-text);
  font-weight:950;
  z-index:1;
}
.simplePreviewTable td span[data-truncated]{
  position:relative;
}
.simplePreviewTable td span[data-truncated]::after{
  content:"…";
  position:absolute;
  right:4px;
  bottom:2px;
  color:var(--mrs-muted);
  font-size:10px;
}
.simpleAdvancedPanel{
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface-2);
  padding:8px 10px;
  margin:6px 0;
}
.simpleAdvancedPanel>summary{
  display:flex;
  justify-content:space-between;
  gap:8px;
  cursor:pointer;
  padding:4px 0;
  color:var(--mrs-text);
  font-size:12px;
}
.simpleAdvancedPanel>summary span{
  color:var(--mrs-muted);
  font-size:10px;
}
.simpleAdvancedPanel[open]{
  padding-bottom:8px;
}
.simpleAdvancedPanel[open]>.simpleFilterBar,
.simpleAdvancedPanel[open]>.simpleColumnTypes,
.simpleAdvancedPanel[open]>.dataQualityPanel{
  margin-top:8px;
}
.simpleContentGrid.no-details{
  grid-template-columns:1fr;
}
.simpleTableTop .spacer{
  flex:1;
}
.simpleTableTop .btn.ghost{
  padding:0 8px;
  font-size:11px;
}
.tableSortButton{
  display:inline-flex;
  align-items:center;
  gap:5px;
  width:100%;
  border:0;
  background:transparent;
  color:inherit;
  font:inherit;
  text-align:left;
  cursor:pointer;
}
.tableSortButton small{
  color:var(--mrs-muted);
  font-size:10px;
}
.simplePreviewTable tr.selected td{
  background:rgba(34,197,94,.12);
}
.simpleRowDetails{
  min-width:0;
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface-2);
  padding:9px;
  max-height:52vh;
  overflow:auto;
}
.rowDetailsGrid{
  display:grid;
  gap:8px;
}
.rowDetailGroup{
  border-top:1px solid var(--mrs-border);
  padding-top:8px;
}
.rowDetailGroup:first-child{
  border-top:0;
  padding-top:0;
}
.rowDetailGroup h4{
  margin:0 0 6px;
  font-size:12px;
}
.rowDetail{
  display:grid;
  grid-template-columns:minmax(90px,.38fr) minmax(0,1fr);
  gap:8px;
  padding:4px 0;
}
.rowDetail span{
  color:var(--mrs-muted);
  font-size:11px;
}
.rowDetail b{
  font-size:12px;
  font-weight:750;
  word-break:break-word;
}
.simpleFileTree{
  display:grid;
  gap:9px;
}
.simpleTreeGroup{
  border:1px solid var(--mrs-border);
  border-radius:var(--mrs-radius-md);
  background:var(--mrs-surface-2);
  overflow:hidden;
}
.simpleTreeGroup>summary{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  min-height:34px;
  padding:8px 10px;
  cursor:pointer;
  list-style:none;
  font-weight:900;
}
.simpleTreeGroup>summary::-webkit-details-marker{
  display:none;
}
.simpleTreeGroup>summary b{
  color:var(--mrs-muted);
  font-size:10px;
}
.simpleTreeItems{
  display:grid;
  gap:2px;
  padding:0 8px 8px;
}
.simpleTreeItem{
  min-height:40px;
  width:100%;
  max-width:100%;
  min-width:0;
  overflow:hidden;
}
.simpleTreeItems{
  min-width:0;
}
.simpleTreeItem:hover{
  transform:none;
}
.simpleTreeItem .itemName{
  min-width:0;
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.simpleTreeItem .itemMeta{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
@media(max-width:560px){
  .files .simpleTreeItem .itemName{
    white-space:nowrap;
    overflow-wrap:normal;
  }
}
.simpleTreeItem .btn{
  flex:0 0 auto;
}
.simpleTreeItem .simpleTreeAction,
.simpleTreeItem .simpleDeleteBtn{
  position:relative;
  z-index:1;
}
.simpleTreeItem .simpleTreeAction{
  margin-left:auto;
}
.simpleTreeItem .simpleDeleteBtn{
  width:28px;
  min-width:28px;
  height:28px;
  padding:0;
  margin-left:4px;
  display:inline-grid;
  place-items:center;
  border-radius:999px;
  font-size:18px;
  line-height:1;
  color:var(--mrs-red);
}
.simpleTreeItem .itemName{
  min-width:0;
  flex:1 1 auto;
}
.simpleTreeMore{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  min-height:34px;
  padding:6px 2px 0;
  color:var(--mrs-muted);
  font-size:11px;
}
.simpleAdvancedList{
  display:grid;
  gap:5px;
  padding:0 10px 10px;
}
.simpleAdvancedList span{
  color:var(--mrs-muted);
  font-size:12px;
}
.simpleChartLarge{
  min-height:360px;
  margin-bottom:10px;
}
@media(max-width:1180px){
  .workspaceTopbar{align-items:stretch;flex-wrap:wrap;max-height:none}
  .workspaceSearchBox{order:1;flex:1 1 260px;width:auto}
  .workspaceTopbar .spacer{display:none}
  .workspaceLayout{grid-template-columns:minmax(260px,1fr) 12px minmax(260px,var(--workspace-side,320px))}
  .simpleDashboardSplit,.simpleContentGrid{grid-template-columns:1fr}
  .chartRegistryFilters{grid-template-columns:repeat(2,minmax(130px,1fr))}
  .chartRegistryFilters>input{grid-column:1/-1}
  .analysisProgress{grid-template-columns:1fr auto}
  .analysisProgressTrack{grid-column:1/-1;grid-row:2}
}
@media(max-width:920px){
  .workspaceTopbar{position:sticky;top:0;z-index:30}
  .workspaceSearchBox{order:1;flex:1 1 calc(100% - 132px);width:auto}
  .workspacePrimary{order:2;flex:0 0 auto}
  .workspaceSecondary,.topbarAdvanced{display:none}
  .workspaceMobileMore{display:block;order:3;flex:0 0 auto}
  .workspaceUserPill{order:4}
  .workspaceMenu{order:5;flex:0 0 auto}
  .workspaceLayout{display:grid;grid-template-columns:1fr;grid-template-rows:auto;min-height:auto;height:auto;padding:8px;gap:8px}
  .workspaceLayout .splitX,.workspaceLayout .splitY{display:none}
  .workspaceLayout .materialsPanel,.workspaceLayout .reader,.workspaceLayout .analytics{grid-column:1;grid-row:auto;display:flex;min-height:320px}
  .advancedMenu,.workspaceMenuPanel{left:0;right:auto}
}
@media(max-width:560px){
  .workspaceSearchBox{flex:1 1 100%}
  .workspacePrimary,.workspaceMobileMore,.workspaceMenu{flex:1 1 calc(50% - 8px);justify-content:center}
  .workspaceTopbar,.workspaceLayout,.workspaceLayout>.panel,.workspaceLayout .content,.simpleDashboard,.chartVisualWorkspace,.chartCatalog{width:100%;max-width:100%;min-width:0}
  .simpleSummaryCards,.autoChartGrid,.chartCandidateList,.chartRegistryFilters{grid-template-columns:minmax(0,1fr)}
  .autoChartCard,.chartCandidateCard,.pdfDiagnostics,.svgChart{max-width:100%;min-width:0}
  .autoChartCard .widgetBody,.autoChartCard .widgetBody>div{max-width:100%;min-width:0;overflow:hidden;contain:inline-size}
  .svgChart{display:block;width:100%;overflow:hidden}
  .workspaceMenuPanel,.advancedMenu{max-width:calc(100vw - 16px)}
}

</style>
</head>
